  const lessons = [
    {group:'FOUNDATIONS',title:'Your first query',time:'5 MIN',level:'STARTER',intro:'SQL is how you ask a database questions. Start with one table, choose the columns you want, and let the data answer.',task:'Find the first five customers. Show each customer’s name and city.',hint:'Use SELECT name, city FROM customers, then add LIMIT 5.',query:'SELECT name, city\nFROM customers\nLIMIT 5;',heading:'Ask a clear question',copy:'A database stores information in tables. Each table has columns (the fields) and rows (the individual records). A query is a question written in a language the database understands.',example:'SELECT name, city\nFROM customers;',caption:'THE SHAPE OF A QUERY',after:'SELECT names the columns you want back. FROM tells SQL where those columns live. The semicolon marks the end of the statement.',tip:'Change the column names in the editor, then press Ctrl + Enter or Run query. Click a table name below to peek at its columns.'},
    {group:'FOUNDATIONS',title:'Choose your columns',time:'6 MIN',level:'STARTER',intro:'A good query returns just the information you need. Pick columns by name, rename them with aliases, or ask for every column while exploring.',task:'Show the product name, category, and price. Rename price to list_price.',hint:'Use price AS list_price in your SELECT list.',query:'SELECT name, category, price AS list_price\nFROM products;',heading:'Be specific about the result',copy:'List column names after SELECT, separated by commas. To inspect an unfamiliar table, SELECT * returns every column. For finished queries, name the columns you actually need.',example:'SELECT name,\n       price AS list_price\nFROM products;',caption:'RENAME A COLUMN',after:'An alias changes the column label in the result. Use AS to make that intent clear. In SQLite, the keyword is optional, but clarity helps when queries grow.',tip:'SELECT * is handy for a quick look. AS gives a result column a friendlier name.'},
    {group:'FOUNDATIONS',title:'Filter rows',time:'8 MIN',level:'STARTER',intro:'Use WHERE to keep only the rows that match a condition. Combine comparisons to narrow a broad table into a useful answer.',task:'Show the name and price of products costing less than 50 that are in stock.',hint:'Put both conditions in WHERE and join them with AND.',query:'SELECT name, price\nFROM products\nWHERE price < 50 AND stock > 0;',heading:'Keep the rows that matter',copy:'WHERE is evaluated for each row. Only rows where the condition is true make it into the result. Use =, >, <, >=, and <> to compare values.',example:"SELECT name, price\nFROM products\nWHERE category = 'Accessories'\n  AND price < 50;",caption:'COMBINE CONDITIONS',after:'Use AND when every condition must be true, OR when either is enough, and parentheses when mixing them. Text values go inside single quotes.',tip:'For a range, try price BETWEEN 10 AND 50. For a set of values, use category IN (\'Books\', \'Accessories\').'},
    {group:'FOUNDATIONS',title:'Sort & limit',time:'6 MIN',level:'STARTER',intro:'Sorting turns a pile of rows into a ranked list. Pair ORDER BY with LIMIT to focus on the top or bottom of a result.',task:'Sort order items by quantity, highest first, and show only three rows.',hint:'ORDER BY quantity DESC comes before LIMIT 3.',query:'SELECT product_id, quantity\nFROM order_items\nORDER BY quantity DESC\nLIMIT 3;',heading:'Put results in order',copy:'Databases do not promise a row order unless you ask. ORDER BY sorts by one or more columns. Add DESC for descending order; ascending order is the default.',example:'SELECT name, price\nFROM products\nORDER BY price DESC\nLIMIT 5;',caption:'TOP FIVE BY PRICE',after:'LIMIT caps the number of returned rows. Sort first, then limit, so the database knows which rows belong at the top.',tip:'Sort ties consistently by adding a second column, like ORDER BY price DESC, name. Use LIMIT 10 OFFSET 10 to skip the first page.'},
    {group:'WORK WITH DATA',title:'Summarize data',time:'9 MIN',level:'BUILDING',intro:'Aggregate functions turn many rows into a useful summary. Group rows by a category to compare totals side by side.',task:'Return each city and the number of customers who live there. Show the largest groups first.',hint:'COUNT(*) counts rows. Group by city, then order by the count alias.',query:'SELECT city, COUNT(*) AS customer_count\nFROM customers\nGROUP BY city\nORDER BY customer_count DESC;',heading:'From rows to summaries',copy:'COUNT, SUM, AVG, MIN, and MAX summarize values. Add GROUP BY to get a separate summary for each distinct group.',example:'SELECT customer_id,\n       SUM(total) AS lifetime_value\nFROM orders\nGROUP BY customer_id;',caption:'REVENUE BY CUSTOMER',after:'Every selected column must either be grouped or aggregated. Use COUNT(*) to count rows, even if some fields are empty.',tip:'Filter individual rows with WHERE. Filter completed groups with HAVING, for example HAVING COUNT(*) > 2.'},
    {group:'WORK WITH DATA',title:'Join tables',time:'12 MIN',level:'BUILDING',intro:'Related information often lives in separate tables. A JOIN combines rows using matching key values, so you can ask richer questions.',task:'Show each order id, its order date, and the customer name. Sort newest order first.',hint:'Join orders to customers where customer_id matches. Give the tables short aliases.',query:'SELECT o.id AS order_id, o.order_date, c.name\nFROM orders AS o\nJOIN customers AS c\n  ON o.customer_id = c.id\nORDER BY o.order_date DESC;',heading:'Bring related tables together',copy:'A JOIN matches rows using a relationship between tables. Here, an order stores a customer_id that points to the customer’s id.',example:'SELECT o.id, c.name, o.total\nFROM orders AS o\nJOIN customers AS c\n  ON o.customer_id = c.id;',caption:'ORDERS WITH CUSTOMER NAMES',after:'This is an inner join: only orders with a matching customer appear. Table aliases (o, c) keep the query readable.',tip:'LEFT JOIN keeps every row from the left table, even without a match. Qualify shared names like id with a table alias.'},
    {group:'GO FURTHER',title:'Subqueries & CTEs',time:'12 MIN',level:'ADVANCING',intro:'When a query starts doing too much at once, give a step its own name. Subqueries and CTEs let you build answers in layers.',task:'Find customers whose average order is above the overall average order total.',hint:'Use a CTE for customer averages, then compare with (SELECT AVG(total) FROM orders).',query:'WITH customer_averages AS (\n  SELECT customer_id, AVG(total) AS avg_total\n  FROM orders\n  GROUP BY customer_id\n)\nSELECT c.name, ROUND(a.avg_total, 2) AS avg_total\nFROM customer_averages AS a\nJOIN customers AS c ON c.id = a.customer_id\nWHERE a.avg_total > (SELECT AVG(total) FROM orders)\nORDER BY avg_total DESC;',heading:'Name a step in the answer',copy:'A subquery is a query nested inside another. A common table expression (CTE) gives a temporary name to a result, making multi-step logic easier to read.',example:'WITH monthly_sales AS (\n  SELECT month, SUM(total) AS revenue\n  FROM orders\n  GROUP BY month\n)\nSELECT * FROM monthly_sales;',caption:'BUILD THEN QUERY',after:'Think of the CTE as a named result available to the query that follows it. You can define multiple CTEs, separated by commas.',tip:'A scalar subquery returns one value. A subquery in FROM can act like a temporary table.'},
    {group:'GO FURTHER',title:'Window functions',time:'15 MIN',level:'ADVANCING',intro:'Window functions calculate across related rows while keeping each row visible. Use them for rankings, running totals, and comparisons.',task:'Show every order with its customer, total, and rank from highest to lowest total within that customer.',hint:'Use ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY total DESC).',query:'SELECT customer_id, id AS order_id, total,\n       ROW_NUMBER() OVER (\n         PARTITION BY customer_id\n         ORDER BY total DESC\n       ) AS order_rank\nFROM orders\nORDER BY customer_id, order_rank;',heading:'Calculate across a window',copy:'Unlike GROUP BY, a window function does not collapse rows. The OVER clause defines which rows to compare and in what order.',example:'SELECT customer_id, total,\n       ROW_NUMBER() OVER (\n         PARTITION BY customer_id\n         ORDER BY total DESC\n       ) AS order_rank\nFROM orders;',caption:'RANK EACH CUSTOMER’S ORDERS',after:'PARTITION BY starts the calculation again for each customer. Other useful window functions include RANK(), LAG(), and running SUM().',tip:'Use ROW_NUMBER when every row needs a unique position. Use RANK when ties should share a rank.'},
    {group:'DATABRICKS SQL',title:'Databricks SQL functions',time:'12 MIN',level:'DATABRICKS',intro:'Databricks SQL adds a rich built-in function library for strings, dates, arrays, JSON, statistics, and more. Learn the patterns and know which ones are portable.',task:'Summarize average product price by category. Use LOWER to normalize labels and ROUND for a readable average.',hint:'SELECT LOWER(category), ROUND(AVG(price), 2) ... GROUP BY LOWER(category).',query:'SELECT LOWER(category) AS category,\n       ROUND(AVG(price), 2) AS avg_price\nFROM products\nGROUP BY LOWER(category)\nORDER BY avg_price DESC;',heading:'A function for every kind of data',copy:'Functions transform values, work with missing data, parse semi-structured records, and calculate statistics. Databricks SQL includes common SQL functions plus Spark-specific functions for arrays, maps, JSON, and approximate analytics.',example:'SELECT LOWER(category) AS category,\n       ROUND(AVG(price), 2) AS avg_price\nFROM products\nGROUP BY LOWER(category);',caption:'PORTABLE SQL FUNCTIONS',after:'LOWER and ROUND are available in both SQLite and Databricks SQL, so this lesson query runs here. The reference examples below use Databricks SQL syntax; this browser runner uses SQLite and cannot execute every Databricks-specific function.',tip:'Start with the shared functions, then check Databricks SQL docs when a function uses arrays, JSON, dates, or approximate statistics.',functionGroups:[{name:'Strings & cleanup',items:[['concat(expr1, expr2, …)','Join values into one string',"concat(first_name, ' ', last_name)"],['split(str, regex)','Split text into an array',"split(email, '@')"],['regexp_extract(str, regex, idx)','Extract a regex capture group',"regexp_extract(code, '([A-Z]+)-', 1)"],['trim(str) · lower(str)','Remove spaces or normalize case','lower(trim(email))']]},{name:'Dates & time',items:[['date_add(date, days)','Add days to a date',"date_add(order_date, 7)"],['datediff(end, start)','Days between two dates',"datediff(current_date(), order_date)"],['date_format(ts, fmt)','Format a date or timestamp',"date_format(order_date, 'yyyy-MM')"]]},{name:'Nulls & safe conversion',items:[['coalesce(a, b, …)','First non-NULL value',"coalesce(city, 'Unknown')"],['try_cast(value AS type)','Cast safely; invalid values become NULL',"try_cast(raw_price AS DECIMAL(10,2))"],['try_divide(a, b)','Divide safely; zero returns NULL','try_divide(revenue, units)']]},{name:'Arrays, JSON & analytics',items:[['explode(array)','Turn array elements into rows','LATERAL VIEW explode(tags) AS tag'],['from_json(json, schema)','Parse JSON into a typed structure',"from_json(payload, 'id BIGINT, city STRING')"],['approx_count_distinct(expr)','Estimate distinct count efficiently','approx_count_distinct(user_id)'],['percentile_approx(value, p)','Estimate a percentile', 'percentile_approx(duration_ms, 0.95)']] }]}
  ];
  const tables={customers:{rows:6,cols:[['id','INTEGER','PK'],['name','TEXT'],['email','TEXT'],['city','TEXT'],['joined_on','TEXT']]},products:{rows:6,cols:[['id','INTEGER','PK'],['name','TEXT'],['category','TEXT'],['price','REAL'],['stock','INTEGER']]},orders:{rows:6,cols:[['id','INTEGER','PK'],['customer_id','INTEGER'],['order_date','TEXT'],['total','REAL'],['status','TEXT']]},order_items:{rows:10,cols:[['id','INTEGER','PK'],['order_id','INTEGER'],['product_id','INTEGER'],['quantity','INTEGER'],['unit_price','REAL']]}};